const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}});
const localToday=()=>{const n=new Date();return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`};
document.querySelectorAll('input[type=date]').forEach(el=>el.min=localToday());
const params=new URLSearchParams(location.search);for(const key of ['checkin','checkout','adults','children']){const el=document.querySelector(`[name=${key}]`);if(el&&params.has(key))el.value=params.get(key)}
function validate(form){const d=new FormData(form);if(!d.has('checkin'))return '';const a=d.get('checkin'),b=d.get('checkout');if(Boolean(a)!==Boolean(b))return 'Please choose both check-in and check-out dates.';if(a&&a<localToday())return 'Please choose a check-in date today or later.';if(a&&b<=a)return 'Check-out must be after check-in.';if(Number(d.get('adults'))+Number(d.get('children'))>4)return 'The apartment accommodates a maximum of four guests, including children.';return ''}
function enquiryLink(data,channel,kind){const names={name:'Full name',email:'Email',phone:'Phone',whatsapp:'WhatsApp',checkin:'Check-in',checkout:'Check-out',adults:'Adults',children:'Children',message:'Message',subject:'Subject'};const text=Array.from(data,([k,v])=>`${names[k]||k}: ${v||'Not provided'}`).join('\n');const subject=kind==='Booking'?'Accommodation enquiry — Flourish Haven Escape':data.get('subject');return channel==='whatsapp'?`https://wa.me/27693364688?text=${encodeURIComponent('Hello Flourish Haven Escape, I would like to enquire about accommodation.\n\n'+text)}`:`mailto:reservations@flourishhavenescape.co.za?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(text)}`}
document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',e=>{const error=validate(form),box=form.querySelector('.form-error');box.textContent=error;if(error){e.preventDefault();box.tabIndex=-1;box.focus();return}if(!form.classList.contains('enquiry'))return;e.preventDefault();const channel=e.submitter?.value==='whatsapp'?'whatsapp':'email',href=enquiryLink(new FormData(form),channel,form.dataset.kind),fallback=form.querySelector('.email-fallback');fallback.href=href;fallback.hidden=false;fallback.textContent=channel==='whatsapp'?'Open WhatsApp draft':'Open email draft';fallback.target=channel==='whatsapp'?'_blank':'_self';fallback.rel='noopener';form.querySelector('.form-status').textContent=`Your ${channel==='whatsapp'?'WhatsApp message':'email'} draft is ready. Please send it in the app. Your enquiry has not been sent by this website, and your stay is not yet confirmed.`;if(channel==='whatsapp')window.open(href,'_blank','noopener');else location.href=href;}));
const lightbox=document.querySelector('.lightbox');
if(lightbox){const photos=[...document.querySelectorAll('.photo-open')],figures=[...document.querySelectorAll('.photo-grid figure')];let current=0,opener=null,touchX=null;const visiblePhotos=()=>photos.filter(p=>!p.closest('figure').hidden);
function show(index){const visible=visiblePhotos();current=(index+visible.length)%visible.length;const img=visible[current].querySelector('img'),large=lightbox.querySelector('img');large.src=img.src;large.alt=img.alt;lightbox.querySelector('.lightbox-caption').textContent=`${img.alt} · ${current+1} / ${visible.length}`;}
photos.forEach(photo=>photo.addEventListener('click',()=>{opener=photo;show(visiblePhotos().indexOf(photo));lightbox.showModal();document.body.classList.add('modal-open')}));
lightbox.querySelector('.lightbox-close').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('close',()=>{document.body.classList.remove('modal-open');opener?.focus()});lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});lightbox.querySelector('.lightbox-prev').addEventListener('click',()=>show(current-1));lightbox.querySelector('.lightbox-next').addEventListener('click',()=>show(current+1));lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();show(current+(e.key==='ArrowRight'?1:-1))}});lightbox.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX},{passive:true});lightbox.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-touchX;if(touchX!==null&&Math.abs(delta)>60)show(current+(delta<0?1:-1));touchX=null},{passive:true});document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));figures.forEach(f=>{f.hidden=button.dataset.filter!=='All'&&f.dataset.category!==button.dataset.filter})}));}
